OUT = ROOT / 'geometry-course/textbook/data/vector-sums.json'


def frame(label, points, arrows=(), lines=()):
    # A visible unit segment makes collinear constructions measurable, including zero results.
    lower=min(y for _,y in points.values())-1.15
    left=min(x for x,_ in points.values())
    points={**points,'U':(left,lower),'V':(left+1,lower)}
    return (label,points,list(arrows),list(lines)+[('U','V')])


def diagram(frames, cases=()):
    all_frames=frames+list(cases)
    points=[p for _,p,_,_ in all_frames]
    descriptions=[(label,list(p),arrows,lines) for label,p,arrows,lines in all_frames]
    return scene(points,descriptions[:len(frames)],descriptions[len(frames):])


def rays(label, vectors):
    pts={'O':(0,0),**vectors}
    return frame(label,pts,[('O',name) for name,v in vectors.items() if v!=(0,0)])


def route(label, moves, names='PQRSTW', *, show='both'):
    p={names[0]:(0,0)}
    current=names[0]
    path=[]
    for name,(dx,dy) in zip(names[1:],moves,strict=False):
        x,y=p[current];dest=(x+dx,y+dy)
        target=next((key for key,value in p.items() if value==dest),name)
        if current!=target:
            p[target]=dest
            path.append((current,target))
        current=target
    assert len(names)>=len(moves)+1
    result=[(names[0],current)] if current!=names[0] else []
    if show=='route': arrows=path
    elif show=='sum': arrows=result
    else: arrows=path+[pair for pair in result if pair not in path]
    return frame(label,p,arrows,path if show=='sum' else [])


def lesson(n, *, pages, kind='exercise', part=None, question, answer, hint, steps, frames, checks, cases=(), caption=None):
    card=make(n,kind=kind,part=part,pages=pages,title=('Задача ' if kind=='exercise' else '')+str(n),
              statement=question,result=answer,hint=hint,stages=steps,picture=diagram(frames,cases),checks=checks)
    card['review']={**card['review'],'reviewer':'Сверено с изданием 2023 года, §2 главы X, печатные с. 230–235. Направления, замкнутые ломаные и варианты переносов проверены независимо по координатам.'}
    card['visualization']['caption']=caption or 'UV — единичный отрезок. Проследи движение от основания каждой стрелки к её острию.'
    if kind=='exercise':
        theory=[87] if n in (941,942) else [87,89] if n==943 else [87,90]
        card['help'][1]['theoryIds']=[f'atanasyan-7-9-theory-{j}-part-1' for j in theory]
        card['help'][1]['text']='Сравни своё построение с определением суммы или разности.'
        card['answer']['prompt']='Запиши свой результат и укажи, откуда и куда идёт итоговая стрелка.'
    return card


